from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/test")
async def test_endpoint(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

client = TestClient(app)

def test_form_then_file():
    files = {"file": ("test.txt", b"hello world")}
    data = {"form_data": "test value"}
    response = client.post("/test", data=data, files=files)
    assert response.status_code == 200, f"Expected 200, got {response.status_code}: {response.text}"
    assert response.json() == {"form_data": "test value", "file": "test.txt"}

if __name__ == "__main__":
    try:
        test_form_then_file()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
EOF
